	if err := validateFields(fieldStrings, InventoryAllowedFields); err != nil {
		return nil, err
	}
	selectFields := buildSelectFieldsTyped(fieldStrings, "inventory")
	if selectFields == "" {
		return nil, fmt.Errorf("no valid fields specified")
	}
